// Parse Telegram update from webhook body
const body = $input.first().json.body;

let from = {};
let chatId = null;
let isCallback = false;
let cbData = null;
let cbId = null;
let text = null;

if (body.callback_query) {
  const cq = body.callback_query;
  from = cq.from || {};
  chatId = cq.message && cq.message.chat ? cq.message.chat.id : (from.id || null);
  isCallback = true;
  cbData = cq.data || null;
  cbId = cq.id || null;
  text = null;
} else if (body.message) {
  const msg = body.message;
  from = msg.from || {};
  chatId = msg.chat ? msg.chat.id : (from.id || null);
  isCallback = false;
  cbData = null;
  cbId = null;
  text = msg.text || null;
}

return [{
  json: {
    from,
    chatId,
    isCallback,
    cbData,
    cbId,
    text
  }
}];

// ============================================================
// MAIN ROUTER — Core bot logic
// ============================================================

const parsed  = $('ParseUpdate').first().json;
const user    = $('UpsertUser').first().json;
const tplRows = $('GetTemplates').all().map(i => i.json);

const { from, chatId, isCallback, cbData, cbId, text } = parsed;

// ---------- Build templates lookup ----------
const templates = {};
for (const row of tplRows) {
  if (!row || !row.key || !row.lang) continue;
  if (!templates[row.key]) templates[row.key] = {};
  templates[row.key][row.lang] = row.text || '';
}

const userLang = user.preferred_language || from.language_code || 'en';

function getTemplate(key, lang) {
  const byKey = templates[key];
  if (!byKey) return key;
  return byKey[lang] || byKey['en'] || key;
}

function tpl(text, vars) {
  if (!text || !vars) return text || '';
  return text.replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? vars[k] : '{' + k + '}'));
}

// ---------- Keyboards ----------
const KB = {
  menu: {
    inline_keyboard: [
      [
        { text: '🛠 Support',  callback_data: 'action_cmd_support'  },
        { text: '💰 Pricing',  callback_data: 'action_cmd_pricing'  }
      ],
      [
        { text: '📱 Setup',    callback_data: 'action_cmd_setup'    },
        { text: '❓ FAQ',      callback_data: 'action_cmd_faq'      }
      ],
      [
        { text: '👤 Account',  callback_data: 'action_cmd_account'  },
        { text: '🌐 Language', callback_data: 'action_cmd_language' }
      ],
      [
        { text: '📢 Channel',  url: 'https://t.me/dopplervpn'       },
        { text: '🙋 Human',    callback_data: 'action_cmd_human'    }
      ]
    ]
  },
  devices: {
    inline_keyboard: [
      [
        { text: '🍎 iPhone',  callback_data: 'action_device_iphone'  },
        { text: '🤖 Android', callback_data: 'action_device_android' }
      ],
      [
        { text: '💻 Mac',     callback_data: 'action_device_mac'    },
        { text: '🖥 Other',   callback_data: 'action_device_other'  }
      ]
    ]
  },
  issues: {
    inline_keyboard: [
      [
        { text: "🚫 Won't connect", callback_data: 'action_issue_noconnect'    },
        { text: '🐢 Slow',          callback_data: 'action_issue_slow'         }
      ],
      [
        { text: '🔌 Disconnects',   callback_data: 'action_issue_disconnects'  },
        { text: '🚧 Blocked',       callback_data: 'action_issue_blocked'      }
      ],
      [
        { text: '💥 App crash',     callback_data: 'action_issue_crash'        },
        { text: '❓ Other',         callback_data: 'action_issue_other'        }
      ]
    ]
  },
  postAi: {
    inline_keyboard: [
      [
        { text: '✅ Yes, solved!',  callback_data: 'action_resolved_yes' },
        { text: '❌ No',            callback_data: 'action_resolved_no'  },
        { text: '🙋 Human',        callback_data: 'action_cmd_human'    }
      ]
    ]
  },
  languages: {
    inline_keyboard: [
      [
        { text: '🇬🇧 English',    callback_data: 'action_lang_en' },
        { text: '🇷🇺 Русский',   callback_data: 'action_lang_ru' },
        { text: '🇩🇪 Deutsch',   callback_data: 'action_lang_de' }
      ],
      [
        { text: '🇫🇷 Français',  callback_data: 'action_lang_fr' },
        { text: '🇪🇸 Español',   callback_data: 'action_lang_es' },
        { text: '🇮🇹 Italiano',  callback_data: 'action_lang_it' }
      ],
      [
        { text: '🇵🇹 Português', callback_data: 'action_lang_pt' },
        { text: '🇺🇦 Українська',callback_data: 'action_lang_uk' },
        { text: '🇹🇷 Türkçe',   callback_data: 'action_lang_tr' }
      ]
    ]
  },
  feedback: {
    inline_keyboard: [
      [
        { text: '👍 Great', callback_data: 'action_feedback_great' },
        { text: '👌 OK',    callback_data: 'action_feedback_ok'    },
        { text: '👎 Poor',  callback_data: 'action_feedback_poor'  }
      ]
    ]
  }
};

// ---------- Helpers ----------
function kbStr(kb) {
  return JSON.stringify(kb);
}

function buildFaqKeyboard() {
  const faqKeys = Object.keys(templates).filter(k => k.startsWith('faq.'));
  const rows = [];
  for (let i = 0; i < faqKeys.length; i += 2) {
    const row = [{ text: faqKeys[i], callback_data: 'action_faq_' + faqKeys[i] }];
    if (faqKeys[i + 1]) row.push({ text: faqKeys[i + 1], callback_data: 'action_faq_' + faqKeys[i + 1] });
    rows.push(row);
  }
  rows.push([{ text: '🏠 Menu', callback_data: 'action_cmd_menu' }]);
  return { inline_keyboard: rows };
}

// ---------- State & input ----------
const botState = user.bot_state || 'idle';
const accountCode = user.account_code || null;
const firstName = from.first_name || 'there';

// Determine effective command/action
let cmd = null;       // '/start', '/menu', etc.
let action = null;    // 'action_device_iphone', etc.
let userText = null;  // plain text from user

if (isCallback && cbData) {
  if (cbData.startsWith('action_cmd_')) {
    // treat as command
    const cmdName = cbData.replace('action_cmd_', '');
    cmd = '/' + cmdName;
  } else if (cbData.startsWith('action_')) {
    action = cbData;
  }
} else if (text) {
  if (text.startsWith('/')) {
    cmd = text.split(' ')[0].toLowerCase();
  } else {
    userText = text;
  }
}

// ---------- Result defaults ----------
let outText = '';
let outKeyboard = null;
let callGrok = false;
let notifyRoman = false;
let notifyPayload = null;
let userUpdate = null;
let feedbackData = null;
let device = user.current_device || null;
let issue = user.current_issue || null;
let lang = userLang;

// ---------- Command handling ----------
if (cmd === '/start') {
  outText = tpl(getTemplate('welcome.main', lang), { user_name: firstName });
  outKeyboard = kbStr(KB.menu);
  userUpdate = { bot_state: 'idle' };

} else if (cmd === '/menu' || cmd === '/help') {
  outText = getTemplate('menu.main', lang);
  outKeyboard = kbStr(KB.menu);
  userUpdate = { bot_state: 'idle' };

} else if (cmd === '/pricing') {
  outText = getTemplate('pricing.info', lang);
  outKeyboard = kbStr(KB.menu);

} else if (cmd === '/setup') {
  outText = getTemplate('setup.guide', lang);
  outKeyboard = kbStr(KB.menu);

} else if (cmd === '/support') {
  outText = getTemplate('troubleshoot.start', lang);
  outKeyboard = kbStr(KB.devices);
  userUpdate = { bot_state: 'troubleshoot_device' };

} else if (cmd === '/human') {
  outText = getTemplate('human.ask_code', lang);
  outKeyboard = null;
  userUpdate = { bot_state: 'awaiting_account_code' };
  notifyRoman = true;
  notifyPayload = {
    type: 'human_requested',
    telegram_id: from.id,
    username: from.username || null,
    first_name: firstName
  };

} else if (cmd === '/account') {
  if (accountCode) {
    outText = tpl(getTemplate('account.linked', lang), { user_name: firstName, account_code: accountCode });
  } else {
    outText = getTemplate('account.not_linked', lang);
    userUpdate = { bot_state: 'awaiting_account_link' };
  }
  outKeyboard = kbStr(KB.menu);

} else if (cmd === '/language') {
  outText = getTemplate('system.language_select', lang);
  outKeyboard = kbStr(KB.languages);
  userUpdate = { bot_state: 'language_select' };

} else if (cmd === '/channel') {
  outText = getTemplate('engagement.channel', lang);
  outKeyboard = kbStr(KB.menu);

} else if (cmd === '/faq') {
  const faqKb = buildFaqKeyboard();
  const faqKeys = Object.keys(templates).filter(k => k.startsWith('faq.'));
  if (faqKeys.length === 0) {
    outText = getTemplate('faq.empty', lang) || 'No FAQs available yet.';
    outKeyboard = kbStr(KB.menu);
  } else {
    outText = getTemplate('faq.list', lang) || 'Choose a topic:';
    outKeyboard = kbStr(faqKb);
  }

} else if (action) {
  // ---------- Action handling ----------

  if (action.startsWith('action_device_')) {
    device = action.replace('action_device_', '');
    outText = getTemplate('troubleshoot.issue', lang);
    outKeyboard = kbStr(KB.issues);
    userUpdate = { bot_state: 'troubleshoot_issue', current_device: device };

  } else if (action.startsWith('action_issue_')) {
    issue = action.replace('action_issue_', '');
    callGrok = true;
    userUpdate = { bot_state: 'post_ai', current_issue: issue };

  } else if (action === 'action_resolved_yes') {
    outText = getTemplate('troubleshoot.resolved_yes', lang);
    outKeyboard = kbStr(KB.feedback);
    userUpdate = { bot_state: 'idle' };

  } else if (action === 'action_resolved_no') {
    outText = getTemplate('human.ask_code', lang);
    outKeyboard = null;
    userUpdate = { bot_state: 'awaiting_account_code' };
    notifyRoman = true;
    notifyPayload = {
      type: 'unresolved_issue',
      telegram_id: from.id,
      username: from.username || null,
      first_name: firstName,
      device: device,
      issue: issue
    };

  } else if (action.startsWith('action_lang_')) {
    const newLang = action.replace('action_lang_', '');
    lang = newLang;
    outText = getTemplate('system.language_changed', newLang);
    outKeyboard = kbStr(KB.menu);
    userUpdate = { bot_state: 'idle', preferred_language: newLang };

  } else if (action.startsWith('action_faq_')) {
    const faqKey = action.replace('action_faq_', '');
    outText = getTemplate(faqKey, lang) || getTemplate('error.unknown', lang);
    outKeyboard = kbStr(KB.menu);

  } else if (action.startsWith('action_feedback_')) {
    const rating = action.replace('action_feedback_', '');
    feedbackData = { telegram_id: from.id, rating: rating };
    outText = getTemplate('feedback.thanks', lang) || 'Thank you for your feedback!';
    outKeyboard = kbStr(KB.menu);
    userUpdate = { bot_state: 'idle' };

  } else {
    outText = getTemplate('error.unknown', lang);
    outKeyboard = kbStr(KB.menu);
  }

} else if (userText) {
  // ---------- State-based text handling ----------

  const greetingRegex = /^(hi|hello|hey|привет|хай|добрый|здравствуй|hola|bonjour|ciao|olá|merhaba)/i;

  if (botState === 'troubleshoot_device') {
    // Treat text as device selection
    const deviceMap = {
      iphone: 'iphone', ios: 'iphone', apple: 'iphone',
      android: 'android', samsung: 'android',
      mac: 'mac', macos: 'mac', macbook: 'mac',
      other: 'other'
    };
    const normalised = userText.toLowerCase().trim();
    device = deviceMap[normalised] || 'other';
    outText = getTemplate('troubleshoot.issue', lang);
    outKeyboard = kbStr(KB.issues);
    userUpdate = { bot_state: 'troubleshoot_issue', current_device: device };

  } else if (botState === 'troubleshoot_issue') {
    issue = userText;
    callGrok = true;
    userUpdate = { bot_state: 'post_ai', current_issue: issue };

  } else if (botState === 'awaiting_account_code') {
    const codeRegex = /^VPN-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}$/i;
    if (userText.toLowerCase() === 'skip') {
      outText = getTemplate('human.escalated', lang);
      outKeyboard = kbStr(KB.menu);
      userUpdate = { bot_state: 'idle' };
      notifyRoman = true;
      notifyPayload = {
        type: 'human_escalation',
        telegram_id: from.id,
        username: from.username || null,
        first_name: firstName,
        account_code: null
      };
    } else if (codeRegex.test(userText.trim())) {
      outText = tpl(getTemplate('human.escalated_with_code', lang), { user_name: firstName, account_code: userText.trim() });
      outKeyboard = kbStr(KB.menu);
      userUpdate = { bot_state: 'idle', account_code: userText.trim() };
      notifyRoman = true;
      notifyPayload = {
        type: 'human_escalation',
        telegram_id: from.id,
        username: from.username || null,
        first_name: firstName,
        account_code: userText.trim()
      };
    } else {
      outText = getTemplate('human.invalid_code', lang) || 'Please enter a valid code (VPN-XXXX-XXXX-XXXX) or type \'skip\'';
      outKeyboard = null;
    }

  } else if (botState === 'awaiting_account_link') {
    const codeRegex = /^VPN-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}$/i;
    if (codeRegex.test(userText.trim())) {
      outText = tpl(getTemplate('account.linked', lang), { user_name: firstName, account_code: userText.trim() });
      outKeyboard = kbStr(KB.menu);
      userUpdate = { bot_state: 'idle', account_code: userText.trim() };
    } else {
      outText = getTemplate('account.invalid_code', lang) || 'Invalid code format. Please enter VPN-XXXX-XXXX-XXXX.';
      outKeyboard = null;
    }

  } else if (botState === 'language_select') {
    outText = getTemplate('system.language_select', lang);
    outKeyboard = kbStr(KB.languages);

  } else if (greetingRegex.test(userText)) {
    outText = tpl(getTemplate('welcome.returning', lang), { user_name: firstName });
    outKeyboard = kbStr(KB.menu);
    userUpdate = { bot_state: 'idle' };

  } else {
    outText = getTemplate('error.unknown', lang);
    outKeyboard = kbStr(KB.menu);
  }

} else {
  // No text, no action, no command
  outText = getTemplate('error.unknown', lang);
  outKeyboard = kbStr(KB.menu);
}

// ---------- Fallback text ----------
if (!outText) {
  outText = getTemplate('error.unknown', lang) || 'Sorry, something went wrong. Please try again.';
}

return [{
  json: {
    chatId,
    text: outText,
    parse_mode: 'HTML',
    reply_markup: outKeyboard,
    callGrok,
    notifyRoman,
    notifyPayload,
    callback_query_id: cbId || null,
    device,
    issue,
    lang,
    userUpdate,
    feedbackData
  }
}];

// Format AI response into a message
const grokResponse = $input.first().json;
const mainData = $('MainRouter').first().json;

let aiText = '';
try {
  aiText = grokResponse.choices[0].message.content || '';
} catch(e) {
  aiText = 'I had trouble generating a response. Please try again or contact human support.';
}

const postAiKeyboard = {
  inline_keyboard: [
    [
      { text: '✅ Yes, solved!',  callback_data: 'action_resolved_yes' },
      { text: '❌ No',            callback_data: 'action_resolved_no'  },
      { text: '🙋 Human',        callback_data: 'action_cmd_human'    }
    ]
  ]
};

const formattedText = '<b>🤖 AI Support</b>\n\n' + aiText + '\n\n<i>Did this solve your issue?</i>';

return [{
  json: {
    chatId: mainData.chatId,
    text: formattedText,
    parse_mode: 'HTML',
    reply_markup: JSON.stringify(postAiKeyboard),
    callGrok: false,
    notifyRoman: mainData.notifyRoman || false,
    notifyPayload: mainData.notifyPayload || null,
    callback_query_id: mainData.callback_query_id || null
  }
}];

const headers = $input.first().json.headers || {};
const body = $input.first().json.body || $input.first().json;

// Accept Telegram webhook updates (have update_id in body)
const isTelegramUpdate = body && (body.update_id !== undefined);

// Accept internal n8n calls with X-Webhook-Secret header
const secret = $env.WEBHOOK_SECRET;
const provided = headers['x-webhook-secret'] || headers['x-telegram-bot-api-secret-token'];
const hasValidSecret = provided && provided === secret;

if (!isTelegramUpdate && !hasValidSecret) {
  throw new Error('Unauthorized: not a Telegram update and no valid webhook secret');
}
return $input.all();
